def solve_graceful():
    n_cliques = 9
    n_vertices = 27
    n_edges = 51

    # Build adjacency list
    adj = [[] for _ in range(n_vertices)]
    edges = []

    # Intra-clique edges
    for g in range(n_cliques):
        for i in range(3):
            for j in range(i+1, 3):
                u, v = g*3+i, g*3+j
                adj[u].append(v)
                adj[v].append(u)
                edges.append((u, v))

    # Inter-clique edges
    for g in range(n_cliques-1):
        for i in range(3):
            u, v = g*3+i, (g+1)*3+i
            adj[u].append(v)
            adj[v].append(u)
            edges.append((u, v))

    print(f"Vertices: {n_vertices}, Edges: {len(edges)}")

    # Try using constraint programming with OR-Tools or simple backtracking
