    labels = [None] * n_vertices
    used_labels = set()
    used_diffs = set()

    def get_edge_diffs_for_vertex(vertex):
        """Get edge diffs that would be created if we assign a label to this vertex"""
        diffs = []
        for neighbor in adj[vertex]:
            if labels[neighbor] is not None:
                diffs.append(abs(labels[neighbor] - labels[vertex]))
        return diffs

    def is_valid_assignment(vertex, label):
        """Check if assigning label to vertex is valid"""
        if label in used_labels:
            return False
        for neighbor in adj[vertex]:
            if labels[neighbor] is not None:
                diff = abs(labels[neighbor] - label)
                if diff in used_diffs:
                    return False
        return True

    def assign(vertex, label):
        labels[vertex] = label
        used_labels.add(label)
        for neighbor in adj[vertex]:
            if labels[neighbor] is not None:
                used_diffs.add(abs(labels[neighbor] - label))

    def unassign(vertex, label):
        labels[vertex] = None
        used_labels.remove(label)
        for neighbor in adj[vertex]:
            if labels[neighbor] is not None:
                used_diffs.remove(abs(labels[neighbor] - label))

    def get_unassigned_neighbors(vertex):
        """Get unassigned neighbors of vertex"""
        return [n for n in adj[vertex] if labels[n] is None]

    def select_next_vertex():
        """Select next vertex using MRV-like heuristic"""
        # Find unassigned vertex with most assigned neighbors
        best = None
        best_score = -1
        for i in range(n_vertices):
            if labels[i] is None:
                score = sum(1 for n in adj[i] if labels[n] is not None)
                if score > best_score:
                    best_score = score
                    best = i
        return best

    def backtrack():
        if len(used_labels) == n_vertices:
            return True

        vertex = select_next_vertex()
        if vertex is None:
            return True

        # Try labels in order of most constrained first
        # (labels that create fewer conflicts)
        candidates = []
        for label in range(n_edges + 1):
            if is_valid_assignment(vertex, label):
                # Count how many future constraints this creates
                future_diffs = set()
                for neighbor in adj[vertex]:
                    if labels[neighbor] is None:
                        # This neighbor will have one more constraint
                        pass
                candidates.append(label)

        random.shuffle(candidates)

        for label in candidates:
            assign(vertex, label)
            if backtrack():
                return True
            unassign(vertex, label)

        return False

    # Start with vertex 0
    # Try different starting labels
    for start_label in [0, 51, 25]:
        labels[0] = start_label
        used_labels.add(start_label)
        print(f"Trying start label {start_label}...")
        if backtrack():
            return labels
        labels[0] = None
        used_labels.clear()

    return None

