    for i in range(3):
        for j in range(i+1, 3):
            edges.append((g*3+i, g*3+j))
# Inter-clique edges
for g in range(n_cliques-1):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))

print(f"Edges: {len(edges)}")

# Encoding: x[v][l] = True if vertex v has label l
# y[e][d] = True if edge e has difference d

# Variable encoding:
# x[v][l]: v in 0..26, l in 0..51 -> var = v*52 + l + 1
# y[e][d]: e in 0..50, d in 1..51 -> var = 27*52 + e*51 + (d-1) + 1 = 1404 + e*51 + d

def x_var(v, l):
    return v * 52 + l + 1

def y_var(e, d):
    return 27 * 52 + e * 51 + d  # d is 1..51

n_x_vars = 27 * 52  # 1404
n_y_vars = 51 * 51  # 2601
total_vars = n_x_vars + n_y_vars

print(f"Total variables: {total_vars}")

solver = Glucose3()

# Each vertex gets exactly one label
for v in range(n_vertices):
    # At least one label
    solver.add_clause([x_var(v, l) for l in range(52)])
    # At most one label (pairwise)
    for l1 in range(52):
        for l2 in range(l1+1, 52):
            solver.add_clause([-x_var(v, l1), -x_var(v, l2)])

# Each edge gets exactly one difference
for e in range(n_edges):
    solver.add_clause([y_var(e, d) for d in range(1, 52)])
    for d1 in range(1, 52):
        for d2 in range(d1+1, 52):
            solver.add_clause([-y_var(e, d1), -y_var(e, d2)])

# All edge differences are distinct (each difference used at most once)
for d in range(1, 52):
    for e1 in range(n_edges):
        for e2 in range(e1+1, n_edges):
            solver.add_clause([-y_var(e1, d), -y_var(e2, d)])

# Link vertex labels to edge differences
for e, (u, v) in enumerate(edges):
    for l1 in range(52):
        for l2 in range(52):
            if l1 != l2:
                d = abs(l1 - l2)
                # If x[u][l1] and x[v][l2], then y[e][d]
                solver.add_clause([-x_var(u, l1), -x_var(v, l2), y_var(e, d)])

print(f"Clauses added, time: {time.time() - start_time:.2f}s")

# Symmetry breaking: vertex 0 has label 0
solver.add_clause([x_var(0, 0)])

# Try to solve
if solver.solve():
    model = solver.get_model()
    print(f"SAT! Time: {time.time() - start_time:.2f}s")

    # Extract solution
    solution = [0] * n_vertices
    for v in range(n_vertices):
        for l in range(52):
            if x_var(v, l) in model:
                solution[v] = l
                break

    print(f"Solution: {solution}")

    # Verify
    edge_diffs = []
    for e, (u, v) in enumerate(edges):
        edge_diffs.append(abs(solution[u] - solution[v]))

    print(f"Edge diffs: {sorted(edge_diffs)}")
    print(f"Unique: {len(set(edge_diffs))}")
else:
    print(f"UNSAT or timeout, Time: {time.time() - start_time:.2f}s")

