import random
import time

random.seed(42)

n_cliques = 9
n_vertices = 27
n_edges = 51

# Build edge list
edges = []
for g in range(n_cliques):
    for i in range(3):
        for j in range(i+1, 3):
            edges.append((g*3+i, g*3+j))
for g in range(n_cliques-1):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))

def compute_edge_diffs(labels):
    return [abs(labels[u] - labels[v]) for u, v in edges]

def score(labels):
    """Count number of unique edge diffs (want 51)"""
    diffs = compute_edge_diffs(labels)
    return len(set(diffs))

def hill_climb():
    best_labels = list(range(n_vertices))
    random.shuffle(best_labels)
    best_score = score(best_labels)

    print(f"Initial score: {best_score}")

    for iteration in range(100000):
        if best_score == 51:
            return best_labels

        # Try swapping two vertices
        i, j = random.sample(range(n_vertices), 2)
        new_labels = best_labels[:]
        new_labels[i], new_labels[j] = new_labels[j], new_labels[i]
        new_score = score(new_labels)

        if new_score > best_score:
            best_labels = new_labels
            best_score = new_score
            if iteration % 1000 == 0:
                print(f"Iteration {iteration}: score = {best_score}")

    return best_labels if best_score == 51 else None

# Try multiple restarts
best_overall = None
best_overall_score = 0

for restart in range(100):
    result = hill_climb()
    if result is not None:
        best_overall = result
        break
    s = score(result) if result else 0
    if s > best_overall_score:
        best_overall_score = s
        best_overall = result
    if restart % 10 == 0:
        print(f"Restart {restart}, best score: {best_overall_score}")

if best_overall and score(best_overall) == 51:
    print(f"Found solution: {best_overall}")
else:
    print(f"Best score: {best_overall_score}")
